        int num = 64;
        while (num >= 4) {
            System.out.println(num);
            num /= 2;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int score = 0;
        do {
            System.out.println("Attempt registered: score = " + score);
            score += 10;
        } while (score < 0);
        System.out.println("Loop terminated with score: " + score);
    }
}

public class Main {
    public static void main(String[] args) {
        int sum = 0;
        int term = 1;
        while (sum < 20) {
            sum += term;
            term++;
        }
        System.out.println("Final Sum: " + sum);
        System.out.println("Terms Added: " + (term - 1));
    }
}

public class Main {
    public static void main(String[] args) {
        int attempt = 1;
        while (attempt <= 3) {
            System.out.println("Attempt " + attempt + ": Incorrect PIN");
            attempt++;
        }
        System.out.println("Card Blocked: Maximum attempts reached!");
    }
}

public class Main {
    public static void main(String[] args) {
        int number = 85042;
        int digits = 0;
        while (number > 0) {
            digits++;
            number /= 10;
        }
        System.out.println("Number of digits: " + digits);
    }
}

public class Main {
    public static void main(String[] args) {
        int balance = 150;
        int month = 1;
        while (balance > 0) {
            balance -= 40;
            if (balance > 0) {
                System.out.println("Month " + month + ": Balance remaining $" + balance);
            } else {
                System.out.println("Month " + month + ": Loan fully cleared!");
            }
            month++;
        }
    }
}
